VoiceProfile neutral_voice_profile() {
  VoiceProfile p;
  p.name = "neutral synthetic voice";
  for (int v = 0; v < kNeutralVowels; v++) {
    VoiceProfile::Vowel entry;
    entry.vowel = kNeutralOrder[v];
    for (int t = 0; t < kNeutralPerVowel; t++) {
      Spectrum s{};
      for (int m = 0; m < kMelBands; m++) s[static_cast<std::size_t>(m)] = kNeutralTemplates[v][t][m];
      entry.templates.push_back(s);
    }
    p.templates.push_back(std::move(entry));
  }
  p.voiced_level = -26;
  return p;
}

